import { LISTINGS, TOTAL_BOXES } from "./data";
import { confidenceAt, ctaLabel, fairPrice, formatUsd, revealedBoxes } from "./score-math";
import { ACCENT_FILL, BORDER, FOCUS } from "./theme";
import { Eyebrow } from "./ui";

/**
 * Section 5 — the closing CTA. Its button label is generated by
 * `ctaLabel(confidence)`, not a hardcoded string, and `confidence` is the
 * same live number the device and ValueSection just read out — so the
 * button text itself changes if you drag further or switch listings before
 * scrolling down. The supporting line cites the checks-visible count and
 * the fair-price estimate the same way.
 */
export default function ClosingCTA({ selectedId, reveal }: { selectedId: string; reveal: number }) {
  const listing = LISTINGS.find((l) => l.id === selectedId) ?? LISTINGS[0];
  const confidence = confidenceAt(listing, reveal);
  const revealed = revealedBoxes(listing, reveal);
  const estimate = fairPrice(listing, confidence);

  return (
    <section id="cta" className="py-16 sm:py-20">
      <div className="mx-auto max-w-[1360px] px-4 sm:px-6 lg:px-8">
        <div className="rounded-2xl border p-8 sm:p-12" style={{ borderColor: BORDER, backgroundColor: "#14151C" }}>
          <Eyebrow>READY WHEN YOU ARE</Eyebrow>
          <h2
            className="mt-4 text-[clamp(1.8rem,1.4rem+1.8vw,2.9rem)] font-extrabold leading-[1.08] tracking-[-0.01em] text-white"
            style={{ fontFamily: "var(--font-display-grotesk)" }}
          >
            You left the {listing.title.toLowerCase()} at {confidence}% confidence.
          </h2>
          <p className="mt-5 text-base font-normal leading-[1.6] text-[#A1A1AA]" style={{ maxWidth: "500px" }}>
            That&rsquo;s {revealed.length} of {TOTAL_BOXES} checks visible and a {formatUsd(estimate)} fair-price
            estimate on this one listing alone — every other listing in the catalog carries the same live
            readout, not just this one.
          </p>
          <div className="mt-8 flex flex-wrap items-center gap-4">
            <a
              href="#preview"
              className={`inline-flex items-center justify-center rounded-full px-7 py-3.5 text-base font-semibold text-white transition-opacity duration-200 hover:opacity-90 motion-reduce:transition-none ${FOCUS}`}
              style={{ backgroundColor: ACCENT_FILL }}
            >
              {ctaLabel(confidence)}
            </a>
            <span className="text-sm font-normal tabular-nums text-[#A1A1AA]">
              Fair price est. {formatUsd(estimate)} on this listing
            </span>
          </div>
        </div>
      </div>
    </section>
  );
}
